<template>
  <div class="task-page">
    <header class="task-hero"><div><small>DAILY OPERATIONS</small><h1>养殖待办</h1><p>把投喂、水质检测、换水和复查安排在一张清单里。</p></div><div class="hero-side"><div class="hero-count"><strong>{{ summary.openCount }}</strong><span>全部待处理</span></div><button type="button" class="plan-trigger" :aria-expanded="showRoutinePlan" @click="showRoutinePlan = !showRoutinePlan">{{ showRoutinePlan ? '收起计划向导' : '快速建日常计划' }}</button><button type="button" class="calendar-export" :disabled="summary.openCount === 0 || exporting" @click="exportCalendar">{{ exporting ? '导出中…' : '导出到日历' }}</button></div></header>
    <el-alert type="info" :closable="false" show-icon title="待办只用于计划与记录"><template #default>请根据现场情况执行养殖操作；涉及用药时仍需核对产品标签并咨询专业人员。</template></el-alert>

    <section v-if="showRoutinePlan" class="routine-plan" aria-labelledby="routine-plan-title">
      <div class="routine-head"><div><small>ROUTINE BUILDER</small><h2 id="routine-plan-title">快速建立日常计划</h2><p>只创建你勾选的周期任务；已有同水体同名任务会自动跳过。</p></div><span>{{ routineForm.presets.length }}/4 已选择</span></div>
      <form @submit.prevent="createRoutinePlan">
        <label class="routine-field"><span>水体名称 *</span><input v-model.trim="routineForm.pondName" required maxlength="64" list="routine-ponds" placeholder="例如：一号池" /><datalist id="routine-ponds"><option v-for="pond in knownPonds" :key="pond" :value="pond" /></datalist></label>
        <label class="routine-field"><span>首次执行时间 *</span><input v-model="routineForm.startAt" required type="datetime-local" :min="minimumRoutineTime" /></label>
        <fieldset><legend>选择需要的计划 *</legend><label v-for="preset in routinePresets" :key="preset.value" class="preset-card"><input v-model="routineForm.presets" type="checkbox" :value="preset.value" /><span><b>{{ preset.title }}</b><small>{{ preset.description }}</small><em>{{ preset.frequency }}</em></span></label></fieldset>
        <div class="routine-actions"><button type="button" @click="showRoutinePlan = false">取消</button><button class="primary" type="submit" :disabled="routineSaving || routineForm.presets.length === 0">{{ routineSaving ? '创建中…' : `创建 ${routineForm.presets.length} 项计划` }}</button></div>
      </form>
    </section>

    <section class="task-summary" aria-label="待办概览">
      <button type="button" :class="{ active: scope === 'ALL' }" :aria-pressed="scope === 'ALL'" @click="setScope('ALL')"><span>全部待处理</span><strong>{{ summary.openCount }}</strong></button>
      <button type="button" :class="{ attention: summary.overdueCount > 0, active: scope === 'OVERDUE' }" :aria-pressed="scope === 'OVERDUE'" @click="setScope('OVERDUE')"><span>已逾期</span><strong>{{ summary.overdueCount }}</strong></button>
      <button type="button" :class="{ active: scope === 'DUE_SOON' }" :aria-pressed="scope === 'DUE_SOON'" @click="setScope('DUE_SOON')"><span>24 小时内</span><strong>{{ summary.dueSoonCount }}</strong></button>
      <button type="button" :class="{ active: scope === 'RECURRING' }" :aria-pressed="scope === 'RECURRING'" @click="setScope('RECURRING')"><span>周期任务</span><strong>{{ summary.recurringCount }}</strong></button>
    </section>

    <div class="task-layout">
      <section class="task-form" :class="{ editing: editingId != null }">
        <div class="form-head"><div><small>{{ editingId != null ? 'EDIT TASK' : 'NEW TASK' }}</small><h2>{{ editingId != null ? '编辑待办' : '新增待办' }}</h2></div><span v-if="editingId != null">#{{ editingId }}</span></div>
        <div v-if="sourceNotice" class="source-notice"><b>{{ sourceNoticeTitle }}</b><span>请确认计划时间和内容后再添加待办。</span></div>
        <form @submit.prevent="save">
          <label><span>事项名称 *</span><input v-model.trim="form.title" required maxlength="100" placeholder="例如：复测一号池水质" /></label>
          <label><span>分类 *</span><select v-model="form.category" required><option v-for="item in categories" :key="item.value" :value="item.value">{{ item.label }}</option></select></label>
          <label><span>关联水体</span><input v-model.trim="form.pondName" maxlength="64" placeholder="可选，例如：一号池" /></label>
          <label><span>计划时间 *</span><input v-model="form.dueAt" required type="datetime-local" /></label>
          <label><span>重复周期（天）</span><input v-model.number="form.repeatDays" type="number" min="1" max="365" step="1" list="repeat-options" placeholder="不重复；填写 1–365 天" /><datalist id="repeat-options"><option :value="1">每天</option><option :value="3">每 3 天</option><option :value="7">每周</option><option :value="14">每两周</option><option :value="30">每 30 天</option></datalist></label>
          <label><span>备注</span><textarea v-model.trim="form.notes" maxlength="500" rows="3" placeholder="记录用量、复查重点或注意事项"></textarea></label>
          <div class="form-actions"><button type="button" @click="resetForm">{{ editingId != null ? '取消编辑' : '清空' }}</button><button class="primary" type="submit" :disabled="saving">{{ saving ? '保存中…' : editingId != null ? '保存修改' : '添加待办' }}</button></div>
        </form>
      </section>

      <section class="task-list" v-loading="loading">
        <div class="list-head"><div><h2>{{ activeListTitle }}</h2><p>{{ status === 'OPEN' ? '未完成项目按计划时间从近到远排列。' : '查看已经完成或全部历史事项。' }}</p></div><div class="status-tabs"><button v-for="item in statuses" :key="item.value" type="button" :class="{ active: status === item.value }" @click="changeStatus(item.value)">{{ item.label }}</button></div></div>
        <form class="task-filters" role="search" @submit.prevent="applyFilters">
          <label><span>搜索任务</span><input v-model.trim="filterDraft.q" maxlength="80" placeholder="事项名称或备注" /></label>
          <label><span>筛选水体</span><select v-model="filterDraft.pondName"><option value="">全部水体</option><option v-for="pond in knownPonds" :key="pond" :value="pond">{{ pond }}</option></select></label>
          <label><span>筛选分类</span><select v-model="filterDraft.category"><option value="">全部分类</option><option v-for="item in categories" :key="item.value" :value="item.value">{{ item.label }}</option></select></label>
          <div class="filter-actions"><button type="submit">筛选</button><button type="button" :disabled="!hasFilters" @click="resetFilters">重置</button></div>
        </form>
        <p v-if="hasFilters" class="filter-result" aria-live="polite">找到 {{ total }} 项符合条件的任务</p>
        <div v-if="tasks.length" class="tasks">
          <article v-for="item in tasks" :key="item.id" :class="['task-item',{ overdue:isOverdue(item), completed:Boolean(item.completedAt) }]">
            <button class="completion" type="button" :aria-label="item.completedAt ? '恢复待办' : '完成待办'" @click="toggleCompletion(item)">{{ item.completedAt ? '✓' : '' }}</button>
            <div class="task-copy"><div><span class="category">{{ categoryLabel(item.category) }}</span><span v-if="item.repeatDays" class="repeat-tag">每 {{ item.repeatDays }} 天</span><span v-if="isOverdue(item)" class="overdue-tag">已逾期</span></div><strong>{{ item.title }}</strong><p v-if="item.notes">{{ item.notes }}</p><div class="task-meta"><span>{{ formatDate(item.dueAt) }}</span><span v-if="item.pondName">{{ item.pondName }}</span><span v-if="item.completedAt">完成于 {{ formatDate(item.completedAt) }}</span></div></div>
            <div class="item-actions"><template v-if="!item.completedAt"><button v-if="item.category === 'WATER_TEST'" type="button" class="record-result" :aria-label="`记录${item.title}的检测结果`" @click="recordWaterQuality(item)">记录结果</button><button type="button" :aria-label="`将${item.title}顺延 1 天`" @click="reschedule(item,1)">顺延 1 天</button><button type="button" :aria-label="`将${item.title}顺延 7 天`" @click="reschedule(item,7)">顺延 7 天</button></template><button type="button" @click="edit(item)">编辑</button><button class="danger" type="button" @click="remove(item)">删除</button></div>
          </article>
        </div>
        <div v-else-if="!loading" class="empty"><b>{{ status === 'OPEN' && scope !== 'ALL' ? `当前没有${activeListTitle}` : status === 'OPEN' ? '当前没有待处理事项' : '暂无对应记录' }}</b><span>新增一个计划，日常操作会更容易追踪。</span></div>
        <el-pagination v-if="total > 20" v-model:current-page="page" layout="prev, pager, next" :page-size="20" :total="total" @current-change="load" />
      </section>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { axiosInstance, http } from '@/utils/http'
const route=useRoute(),router=useRouter()

type TaskStatus='OPEN'|'COMPLETED'|'ALL'
type TaskScope='ALL'|'OVERDUE'|'DUE_SOON'|'RECURRING'
type TaskItem={id:number;title:string;category:string;pondName?:string;dueAt:string;notes?:string;repeatDays?:number;completedAt?:string|null;createdAt:string;updatedAt:string;nextDueAt?:string|null}
type TaskSummary={openCount:number;overdueCount:number;dueSoonCount:number;recurringCount:number}
type RoutinePlanResult={created:TaskItem[];skippedPresets:string[]}
const categories=[{value:'FEEDING',label:'投喂'},{value:'WATER_TEST',label:'水质检测'},{value:'WATER_CHANGE',label:'换水'},{value:'MEDICATION',label:'用药/复查'},{value:'OBSERVATION',label:'日常观察'},{value:'OTHER',label:'其他'}]
const statuses:{value:TaskStatus;label:string}[]=[{value:'OPEN',label:'待处理'},{value:'COMPLETED',label:'已完成'},{value:'ALL',label:'全部'}]
function localInput(value=new Date().toISOString()){const date=new Date(value);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function emptyForm(){const tomorrow=new Date(Date.now()+24*60*60*1000);return{title:'',category:'WATER_TEST',pondName:'',dueAt:localInput(tomorrow.toISOString()),notes:'',repeatDays:undefined as number|undefined}}
const form=ref(emptyForm()),editingId=ref<number|null>(null),tasks=ref<TaskItem[]>([]),status=ref<TaskStatus>('OPEN'),scope=ref<TaskScope>('ALL'),page=ref(1),total=ref(0),loading=ref(false),saving=ref(false),exporting=ref(false)
const summary=ref<TaskSummary>({openCount:0,overdueCount:0,dueSoonCount:0,recurringCount:0})
const showRoutinePlan=ref(false),routineSaving=ref(false),knownPonds=ref<string[]>([])
const routinePresets=[{value:'FEEDING',title:'日常投喂',description:'根据天气、水温和摄食调整投喂量',frequency:'每天'},{value:'OBSERVATION',title:'巡塘观察',description:'观察活动、浮头、体表和死亡情况',frequency:'每天'},{value:'WATER_TEST',title:'检测水质',description:'记录水温、pH、溶氧、氨氮和亚硝酸盐',frequency:'每 7 天'},{value:'EQUIPMENT_CHECK',title:'检查增氧与供电设备',description:'检查设备、线路与备用供电',frequency:'每 7 天'}]
const defaultRoutineTime=()=>{const next=new Date();next.setDate(next.getDate()+1);next.setHours(8,0,0,0);return localInput(next.toISOString())}
const routineForm=ref({pondName:'',startAt:defaultRoutineTime(),presets:['OBSERVATION','WATER_TEST'] as string[]})
const minimumRoutineTime=computed(()=>localInput(new Date().toISOString()))
const emptyFilters=()=>({q:'',pondName:'',category:''})
const filterDraft=ref(emptyFilters()),filters=ref(emptyFilters())
const hasFilters=computed(()=>Boolean(filters.value.q||filters.value.pondName||filters.value.category))
const sourceNotice=ref(false)
const sourceKind=ref('')
const sourceNoticeTitle=computed(()=>sourceKind.value==='diagnosis'?'已引用诊断报告':'已引用异常水质记录')
const activeListTitle=computed(()=>status.value!=='OPEN'?'任务清单':({ALL:'待处理任务',OVERDUE:'逾期任务',DUE_SOON:'24 小时内任务',RECURRING:'周期任务'} as Record<TaskScope,string>)[scope.value])
async function load(){loading.value=true;try{const data=await http.get<any>('/api/tasks',{status:status.value,scope:scope.value,q:filters.value.q,pondName:filters.value.pondName,category:filters.value.category,page:page.value-1,size:20});tasks.value=data.content||[];total.value=data.totalElements||0}finally{loading.value=false}}
async function loadSummary(){summary.value=await http.get<TaskSummary>('/api/tasks/summary')}
async function refresh(){await Promise.all([load(),loadSummary()])}
async function loadPonds(){const results=await Promise.allSettled([http.get<string[]>('/api/water-quality/ponds'),http.get<string[]>('/api/tasks/ponds')]);knownPonds.value=[...new Set(results.flatMap(result=>result.status==='fulfilled'?result.value:[]))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function applyFilters(){filters.value={...filterDraft.value};page.value=1;load()}
function resetFilters(){filterDraft.value=emptyFilters();filters.value=emptyFilters();page.value=1;load()}
async function createRoutinePlan(){if(!routineForm.value.presets.length)return;routineSaving.value=true;try{const result=await http.post<RoutinePlanResult>('/api/tasks/routine-plan',{pondName:routineForm.value.pondName,startAt:new Date(routineForm.value.startAt).toISOString(),presets:routineForm.value.presets});const skipped=result.skippedPresets.length;ElMessage.success(skipped?`已创建 ${result.created.length} 项，跳过 ${skipped} 项已有计划`:`已创建 ${result.created.length} 项日常计划`);showRoutinePlan.value=false;routineForm.value={pondName:'',startAt:defaultRoutineTime(),presets:['OBSERVATION','WATER_TEST']};filterDraft.value=emptyFilters();filters.value=emptyFilters();status.value='OPEN';scope.value='ALL';page.value=1;await Promise.all([refresh(),loadPonds()])}finally{routineSaving.value=false}}
async function save(){saving.value=true;try{const wasEditing=editingId.value!=null;const payload={...form.value,dueAt:new Date(form.value.dueAt).toISOString()};if(wasEditing)await http.put(`/api/tasks/${editingId.value}`,payload);else await http.post('/api/tasks',payload);ElMessage.success(wasEditing?'待办已更新':'待办已添加');resetForm();if(!wasEditing){filterDraft.value=emptyFilters();filters.value=emptyFilters()}if(route.query.source)await router.replace('/fish/tasks');status.value='OPEN';page.value=1;await Promise.all([refresh(),loadPonds()])}finally{saving.value=false}}
function edit(item:TaskItem){editingId.value=item.id;form.value={title:item.title,category:item.category,pondName:item.pondName||'',dueAt:localInput(item.dueAt),notes:item.notes||'',repeatDays:item.repeatDays};window.scrollTo({top:0,behavior:'smooth'})}
function resetForm(){editingId.value=null;form.value=emptyForm();sourceNotice.value=false;sourceKind.value=''}
async function toggleCompletion(item:TaskItem){const result=await http.patch<TaskItem>(`/api/tasks/${item.id}/completion`,{completed:!item.completedAt});ElMessage.success(item.completedAt?'待办已恢复':result.nextDueAt?`待办已完成，下一期已安排在 ${formatDate(result.nextDueAt)}`:'待办已完成');await refresh()}
async function reschedule(item:TaskItem,days:number){await http.patch(`/api/tasks/${item.id}/reschedule`,{days});ElMessage.success(`“${item.title}”已顺延 ${days} 天`);await refresh()}
function recordWaterQuality(item:TaskItem){router.push({path:'/fish/water-quality',query:{pond:item.pondName||'',taskId:String(item.id),taskTitle:item.title}})}
async function exportCalendar(){exporting.value=true;try{const blob=await axiosInstance.get<any,Blob>('/api/tasks/calendar.ics',{responseType:'blob'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`养殖待办-${new Date().toISOString().slice(0,10)}.ics`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);ElMessage.success(`已导出 ${summary.value.openCount} 项待办，可导入手机或桌面日历`)}finally{exporting.value=false}}
async function remove(item:TaskItem){await ElMessageBox.confirm(`确定删除“${item.title}”吗？`,'删除待办',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await http.delete(`/api/tasks/${item.id}`);if(editingId.value===item.id)resetForm();ElMessage.success('待办已删除');await refresh()}
function changeStatus(value:TaskStatus){status.value=value;if(value!=='OPEN')scope.value='ALL';page.value=1;load()}
function setScope(value:TaskScope){scope.value=value;status.value='OPEN';page.value=1;load()}
function categoryLabel(value:string){return categories.find(item=>item.value===value)?.label||'其他'}
function isOverdue(item:TaskItem){return !item.completedAt&&new Date(item.dueAt).getTime()<Date.now()}
function formatDate(value:string){return new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}
function queryText(value:unknown,max:number){const text=Array.isArray(value)?value[0]:value;return typeof text==='string'?text.slice(0,max):''}
function applyPrefill(){const source=queryText(route.query.source,32);if(!['water-quality','diagnosis'].includes(source))return;const category=queryText(route.query.category,32);form.value={...form.value,title:queryText(route.query.title,100),pondName:queryText(route.query.pond,64),category:categories.some(item=>item.value===category)?category:source==='diagnosis'?'MEDICATION':'WATER_TEST',notes:queryText(route.query.notes,500)};sourceKind.value=source;sourceNotice.value=true}
onMounted(()=>{applyPrefill();refresh();loadPonds()})
</script>

<style scoped>
.source-notice{display:grid;gap:3px;margin-top:14px;padding:10px 12px;border-left:3px solid var(--c-cyan);border-radius:6px;background:var(--c-cyan-dim);color:var(--c-text-2);font-size:11px}.source-notice b{color:var(--c-cyan)}
.task-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}.task-summary>button{display:flex;align-items:center;justify-content:space-between;min-height:76px;padding:14px 16px;border:1px solid var(--c-border);border-radius:11px;background:var(--c-bg-card);font:inherit;cursor:pointer;transition:border-color .2s,transform .2s,box-shadow .2s}.task-summary>button:hover,.task-summary>button:focus-visible{border-color:var(--c-purple);transform:translateY(-1px);outline:none}.task-summary>button.active{border-color:var(--c-purple);box-shadow:0 0 0 2px rgba(115,87,216,.13)}.task-summary span{color:var(--c-text-3);font-size:11px;font-weight:700}.task-summary strong{color:var(--c-text);font-size:24px}.task-summary .attention{border-color:rgba(214,69,69,.46);background:linear-gradient(120deg,rgba(214,69,69,.08),transparent),var(--c-bg-card)}.task-summary .attention strong{color:#d64545}
.task-page{max-width:1180px;margin:auto}.task-hero{min-height:170px;display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:14px;padding:28px;border:1px solid var(--c-border);border-radius:14px;background:radial-gradient(circle at 85% 20%,rgba(115,87,216,.18),transparent 32%),var(--c-bg-card)}.task-hero small,.form-head small{color:var(--c-purple);font:800 10px ui-monospace;letter-spacing:.18em}.task-hero h1{margin:8px 0;color:var(--c-text);font-size:34px}.task-hero p,.list-head p{margin:0;color:var(--c-text-3);line-height:1.6}.hero-side{display:grid;justify-items:center;gap:9px}.hero-count{min-width:130px;text-align:center}.hero-count strong,.hero-count span{display:block}.hero-count strong{color:var(--c-purple);font-size:42px}.hero-count span{color:var(--c-text-3);font-size:11px}.calendar-export,.plan-trigger{min-height:40px;padding:0 14px;border:1px solid var(--c-purple);border-radius:8px;background:rgba(115,87,216,.1);color:var(--c-purple);font-weight:800;cursor:pointer}.plan-trigger{border-color:var(--c-cyan);background:var(--c-cyan-dim);color:var(--c-cyan)}.calendar-export:focus-visible,.plan-trigger:focus-visible{outline:2px solid var(--c-cyan);outline-offset:2px}.calendar-export:disabled{opacity:.48;cursor:not-allowed}.task-layout{display:grid;grid-template-columns:minmax(290px,.7fr) minmax(0,1.3fr);gap:16px;margin-top:16px}.task-form,.task-list{padding:20px;border:1px solid var(--c-border);border-radius:12px;background:var(--c-bg-card)}.task-form.editing{border-color:#c87900}.form-head,.list-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.form-head h2,.list-head h2{margin:5px 0;color:var(--c-text)}.form-head>span{color:#c87900;font:700 11px ui-monospace}.task-form form{display:grid;gap:12px;margin-top:18px}.task-form label{display:grid;gap:6px;color:var(--c-text-2);font-size:11px;font-weight:700}.task-form input,.task-form select,.task-form textarea{width:100%;min-height:43px;padding:9px 11px;bor